<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { api } from '@/api'; import type { Account } from '@/types'
const accounts=ref<Account[]>([]),done=ref('');const form=ref({sourceAccountId:'',destinationAccountId:'',amount:0,occurredOn:new Date().toISOString().slice(0,10),description:''}); async function load(){accounts.value=await api.accounts(); form.value.sourceAccountId ||=accounts.value[0]?.id??'';form.value.destinationAccountId ||=accounts.value[1]?.id??''} async function save(){if(form.value.sourceAccountId===form.value.destinationAccountId)return; await api.createTransfer(form.value);done.value='Transfer został zapisany.';form.value.amount=0; await load()}onMounted(load)
</script>
<template><section class="panel transfer-panel"><p class="hint">Transfer przenosi środki między kontami. Nie zostanie uwzględniony jako przychód ani wydatek w raportach.</p><form @submit.prevent="save"><div class="transfer-grid"><label>Z konta<select v-model="form.sourceAccountId"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><div class="arrow">→</div><label>Na konto<select v-model="form.destinationAccountId"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label></div><label>Kwota<input type="number" min="0.01" step="0.01" v-model.number="form.amount" required/></label><label>Data<input type="date" v-model="form.occurredOn" required/></label><label>Opis <input v-model.trim="form.description" placeholder="np. Zasilenie budżetu domowego"/></label><button class="button primary">Wykonaj transfer</button><p class="success" v-if="done">{{done}}</p></form></section></template>
